From 9f4e3948225f65dcf9d9c940252c1263d5479622 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:21:43 +0100
Subject: [PATCH] libs/handler: keep the first wired card connected when
 connecting a second

A wired profile that isn't restricted to a device is listed for every
wired card, but connecting it on a second card took the first one down.
Let such a profile be activated on several devices when this happens.

BUG: 478207
---
 libs/handler.cpp | 38 +++++++++++++++++++++++++++++++++++++-
 libs/handler.h   |  2 +-
 2 files changed, 38 insertions(+), 2 deletions(-)

diff --git a/libs/handler.cpp b/libs/handler.cpp
index 1a8d79746..de6e7b566 100644
--- a/libs/handler.cpp
+++ b/libs/handler.cpp
@@ -34,6 +34,7 @@
 #include <QIcon>
 #include <QStringBuilder>

+#include <algorithm>
 #include <memory>

 #include <KIO/OpenUrlJob>
@@ -110,7 +111,7 @@ void Handler::activateConnection(const QString &connection, const QString &devic
     activateConnectionInternal(connection, device, specificObject);
 }

-QCoro::Task<> Handler::activateConnectionInternal(const QString &connection, const QString &device, const QString &specificObject)
+QCoro::Task<> Handler::activateConnectionInternal(QString connection, QString device, QString specificObject)
 {
     NetworkManager::Connection::Ptr con = NetworkManager::findConnection(connection);

@@ -206,6 +207,41 @@ QCoro::Task<> Handler::activateConnectionInternal(const QString &connection, con
     }

     QPointer<Handler> thisGuard(this);
+
+    // A profile is active on only one device at a time by default, so connecting a wired profile that isn't restricted
+    // to a device on a second wired card would take the first card down. Let it be activated on both instead.
+    if (con->settings()->connectionType() == NetworkManager::ConnectionSettings::Wired && con->settings()->interfaceName().isEmpty()) {
+        const auto activeConnections = NetworkManager::activeConnections();
+        const bool activeOnOtherDevice = std::ranges::any_of(activeConnections, [&con, &device](const NetworkManager::ActiveConnection::Ptr &active) {
+            return active->uuid() == con->uuid() && !active->devices().contains(device);
+        });
+        if (activeOnOtherDevice) {
+            const QDBusMessage getSettings = QDBusMessage::createMethodCall(QStringLiteral(NM_DBUS_SERVICE),
+                                                                            con->path(),
+                                                                            QStringLiteral(NM_DBUS_INTERFACE_SETTINGS_CONNECTION),
+                                                                            QStringLiteral("GetSettings"));
+            QDBusReply<NMVariantMapMap> settingsReply = co_await QDBusConnection::systemBus().asyncCall(getSettings);
+            if (!thisGuard) {
+                co_return;
+            }
+            if (settingsReply.isValid()) {
+                NMVariantMapMap settings = settingsReply.value();
+                QVariantMap &connectionSetting = settings[QStringLiteral(NM_SETTING_CONNECTION_SETTING_NAME)];
+                const int multiConnect = connectionSetting.value(QStringLiteral(NM_SETTING_CONNECTION_MULTI_CONNECT)).toInt();
+                if (multiConnect == NM_CONNECTION_MULTI_CONNECT_DEFAULT || multiConnect == NM_CONNECTION_MULTI_CONNECT_SINGLE) {
+                    connectionSetting[QStringLiteral(NM_SETTING_CONNECTION_MULTI_CONNECT)] = int(NM_CONNECTION_MULTI_CONNECT_MANUAL_MULTIPLE);
+                    QDBusReply<void> updateReply = co_await con->update(settings);
+                    if (!thisGuard) {
+                        co_return;
+                    }
+                    if (!updateReply.isValid()) {
+                        qCWarning(PLASMA_NM_LIBS_LOG) << "Failed to allow" << con->name() << "on several devices:" << updateReply.error().message();
+                    }
+                }
+            }
+        }
+    }
+
     QDBusReply<QDBusObjectPath> reply = co_await NetworkManager::activateConnection(connection, device, specificObject);
     if (!thisGuard) {
         co_return;
diff --git a/libs/handler.h b/libs/handler.h
index 64a8425de..5d24f4204 100644
--- a/libs/handler.h
+++ b/libs/handler.h
@@ -146,7 +146,7 @@ Q_SIGNALS:

 private:
     QCoro::Task<> addAndActivateConnectionDBus(const NMVariantMapMap &map, const QString &device, const QString &specificObject);
-    QCoro::Task<> activateConnectionInternal(const QString &connection, const QString &device, const QString &specificParameter);
+    QCoro::Task<> activateConnectionInternal(QString connection, QString device, QString specificParameter);
     QCoro::Task<> addAndActivateConnectionInternal(const QString &device, const QString &specificParameter, const QString &password = QString());
     QCoro::Task<> deactivateConnectionInternal(const QString &connection, const QString &device);
     QCoro::Task<> removeConnectionInternal(const QString &connection);
